export function getEmbeddedPdb(pdbId: string, chain?: string): string | null {
  const key = chain ? `${pdbId.toUpperCase()}_${chain.toUpperCase()}` : pdbId.toUpperCase();
  if (PRESET_STRUCTURES[key]) return PRESET_STRUCTURES[key];
  if (PRESET_STRUCTURES[`${pdbId.toUpperCase()}_FULL`]) return PRESET_STRUCTURES[`${pdbId.toUpperCase()}_FULL`];
  return null;
}
